  --vc-header-ctrl-border-hover: rgba(212, 168, 136, 0.55);
  --vc-header-ctrl-blur: 0px;
  --vc-header-menu-frost-blur: 12px;
  --vc-header-menu-frost-bg:
    radial-gradient(ellipse 104% 76% at 16% 0%, rgba(236, 205, 176, 0.16), transparent 50%),
    linear-gradient(180deg, rgba(28, 20, 15, 0.9), rgba(10, 8, 6, 0.94));
  --vc-support-hero-border: rgba(110, 231, 183, 0.12);
  --vc-support-hero-shadow: 0 24px 80px rgba(0, 0, 0, 0.34);
  --vc-support-hero-bg:
