  --vc-reviews-glow-rgb: 16, 185, 129;
  --vc-reviews-loading-overlay-bg:
    radial-gradient(ellipse 92% 74% at 50% 38%, rgba(6, 78, 59, 0.55) 0%, rgba(8, 22, 24, 0.88) 48%, #040807 100%);
