input:not([type="hidden"]):not(:disabled),
select:not(:disabled),
summary,
label[for],
.vc-icon-btn,
.vc-notif-summary,
.vc-mobile-nav-toggle,
.cursor-pointer,
[onclick] {
  /* 20260907cursorFix2: coffee ← coffe.gif (user WebP→GIF) scaled ~24px, transparent GIF only */
  cursor: var(--vc-cursor-pointer); /* 20260913cursorStatic1 */
}
input[type="text"]:not(:disabled),
input[type="search"]:not(:disabled),
input[type="email"]:not(:disabled),
input[type="password"]:not(:disabled),
input[type="url"]:not(:disabled),
input[type="tel"]:not(:disabled),
input[type="number"]:not(:disabled),
input:not([type]):not(:disabled),
textarea:not(:disabled),
[contenteditable="true"] {
  cursor: text;
}
button:disabled,
[disabled],
[aria-disabled="true"] {
  cursor: not-allowed;
}
html::-webkit-scrollbar {
  width: 11px;
  height: 11px;
}
html::-webkit-scrollbar-track {
  background: linear-gradient(180deg, #140f0c 0%, #0a0806 100%);
  border-radius: 999px;
}
html::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #7a5a45 0%, #4a3428 55%, #3d2a1f 100%);
  border-radius: 999px;
  border: 2px solid #0f0b09;
  box-shadow: inset 0 1px 0 rgba(212, 181, 152, 0.22);
}
html::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, #8f6b52 0%, #5c4033 100%);
}
/* scrollbarPhoneFlat1: telefono — thumb piatto, niente inset “blur” in cima */
@media (max-width: 1199.98px), (pointer: coarse) {
  html {
    scrollbar-width: thin;
    scrollbar-color: #5c4033 #0f0b09;
  }
  html::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  html::-webkit-scrollbar-track {
    background: #0f0b09;
    border-radius: 999px;
  }
  html::-webkit-scrollbar-thumb {
    background: #5c4033;
    border-radius: 999px;
    border: 1px solid #0f0b09;
    box-shadow: none;
  }
  html::-webkit-scrollbar-thumb:hover {
    background: #6b4e3d;
  }
}
.vc-body {
  position: relative;
  min-height: 100vh;
  color: #ebe0d6;
  background-color: #080605;
  background-image:
    radial-gradient(ellipse 90% 70% at 92% 8%, rgba(var(--vc-sand-rgb), 0.1), transparent 52%),
    radial-gradient(ellipse 130% 95% at 50% -8%, rgba(130, 78, 48, 0.34), transparent 62%),
    radial-gradient(ellipse 100% 75% at 100% 32%, rgba(var(--vc-mocha-rgb), 0.22), transparent 56%),
    radial-gradient(ellipse 90% 70% at 0% 68%, rgba(48, 32, 22, 0.26), transparent 58%),
    linear-gradient(180deg, #0a0d10 0%, #100b08 18%, #15100c 38%, #120d0a 55%, #0e0a07 78%, #080605 100%);
  background-attachment: scroll;
  background-repeat: no-repeat;
}
.vc-body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 85% 70% at 50% 0%, rgba(var(--vc-mocha-rgb), 0.22), transparent 55%);
  mix-blend-mode: normal;
  opacity: 0.85;
}
.vc-body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.045;
  background-image:
    repeating-linear-gradient(0deg,
      transparent,
      transparent 2px,
      rgba(255, 255, 255, 0.04) 2px,
      rgba(255, 255, 255, 0.04) 3px),
    repeating-linear-gradient(90deg,
      transparent,
      transparent 2px,
      rgba(0, 0, 0, 0.05) 2px,
      rgba(0, 0, 0, 0.05) 3px);
}
