.vc-notif-dropdown:not([open]) .vc-notif-summary:has(#vc-notif-badge:not([hidden])):hover > i.fa-bell-o,
.vc-notif-dropdown:not([open]) .vc-notif-summary:has(#vc-notif-badge:not([hidden])):hover > i.fa-bell {
  animation: vc-notif-bell-ring 0.7s ease-in-out 1;
}
