.vc-notif-dropdown:not([open]) .vc-notif-summary:has(#vc-notif-badge:not([hidden])).vc-notif-summary--pulse > i.fa-bell-o,
.vc-notif-dropdown:not([open]) .vc-notif-summary:has(#vc-notif-badge:not([hidden])).vc-notif-summary--pulse > i.fa-bell {
  animation: vc-notif-bell-ring 0.55s ease-in-out 3;
}
@keyframes vc-notif-bell-pulse {
  0%,
  100% {
    transform: scale(1);
    filter: brightness(1);
  }
  50% {
    transform: scale(1.08);
    filter: brightness(1.18);
  }
}
@keyframes vc-notif-bell-ring {
  0%,
  100% {
    transform: rotate(0deg);
  }
  12% {
    transform: rotate(14deg);
  }
  28% {
    transform: rotate(-12deg);
  }
  44% {
    transform: rotate(9deg);
  }
  58% {
    transform: rotate(-6deg);
  }
  72% {
    transform: rotate(3deg);
  }
  86% {
    transform: rotate(-1.5deg);
  }
}
@keyframes vc-notif-bell-attention {
  0%,
  78%,
  100% {
    transform: rotate(0deg);
  }
  82% {
    transform: rotate(10deg);
  }
  86% {
    transform: rotate(-8deg);
  }
  90% {
    transform: rotate(6deg);
  }
  94% {
    transform: rotate(-3deg);
  }
  97% {
    transform: rotate(1deg);
  }
}
@media (prefers-reduced-motion: reduce) {
