.vc-visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}
[data-premium-lock].is-premium-locked {
  position: relative;
}
[data-premium-lock].is-premium-locked::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 0.75rem;
  background: rgba(8, 6, 10, 0.28);
  pointer-events: none;
}
[data-premium-lock].is-premium-locked input:disabled,
