.vc-img-lb {
  position: fixed;
  inset: 0;
  z-index: 220000;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.16s ease, visibility 0.16s ease;
}

.vc-img-lb.is-open {
  pointer-events: auto;
  visibility: visible;
  opacity: 1;
}

.vc-img-lb__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  margin: 0;
  padding: 0;
  cursor: var(--vc-cursor-pointer, pointer);
  background: rgba(6, 4, 3, 0.88);
}

.vc-img-lb__stage {
  position: relative;
  z-index: 1;
  width: min(100%, 1100px);
  height: min(100%, 100dvh);
  max-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 0.65rem 0.65rem 0.85rem;
  box-sizing: border-box;
}

.vc-img-lb__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.15rem 0.2rem 0.55rem;
  color: #f3e6d8;
  flex-shrink: 0;
}

.vc-img-lb__counter {
  font-size: 0.92rem;
  letter-spacing: 0.02em;
  color: rgba(243, 230, 216, 0.82);
  min-height: 1.2em;
}

.vc-img-lb__actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.vc-img-lb__btn,
.vc-img-lb__nav {
  appearance: none;
  border: 1px solid rgba(212, 168, 136, 0.28);
  background: rgba(28, 20, 16, 0.82);
  color: #f3e6d8;
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 0.85rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: var(--vc-cursor-pointer, pointer);
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.12s ease;
}

.vc-img-lb__btn:hover,
