  background: rgba(48, 34, 26, 0.95);
  border-color: rgba(212, 168, 136, 0.48);
}

.vc-img-lb__btn:active,
.vc-img-lb__nav:active {
  transform: scale(0.96);
}

.vc-img-lb__btn--close {
  border-color: rgba(212, 168, 136, 0.42);
}

.vc-img-lb__nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 2.7rem;
  height: 2.7rem;
}

